            continue
        cols = [c for c, v in enumerate(row) if v != bg]
        if not cols:
            continue
        last = max(cols)
        if last < w - 1 and any(row[c] == bg for c in range(min(cols), last)):
            for c in range(last + 1, w):
                out[r][c] = 1

